import{_ as s,o as a,c as o,al as i,j as t}from"./chunks/framework.7vp1BMOE.js";const k=JSON.parse('{"title":"PteroSim Simulation","description":"","frontmatter":{},"headers":[],"relativePath":"uk/sim_pterosim/index.md","filePath":"uk/sim_pterosim/index.md"}'),n={name:"uk/sim_pterosim/index.md"};function r(l,e,h,p,d,u){return a(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="pterosim-simulation" tabindex="-1">PteroSim Simulation <a class="header-anchor" href="#pterosim-simulation" aria-label="Permalink to &quot;PteroSim Simulation&quot;">​</a></h1><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>This simulator is <a href="./../simulation/community_supported_simulators">community supported and maintained</a>. It may or may not work with current versions of PX4 and may be removed in future releases. Дивіться <a href="./../dev_setup/dev_env">Встановлення інструментарію</a> для інформації про середовища та інструменти, що підтримуються основною командою розробників.</p></div><p><a href="https://github.com/PteroLabsAI/PteroSim-UAV-Simulator" target="_blank" rel="noreferrer">PteroSim</a> is proprietary simulation software that can be used with PX4 for <a href="./../simulation/#sitl-simulation-environment">Software-In-The-Loop (SITL)</a> simulation. PX4 runs as the flight controller, while PteroSim provides the vehicle dynamics, visual scene, and simulated sensor inputs through a built-in HIL bridge. PteroSim uses the <a href="./../simulation/#simulator-mavlink-api">Simulator MAVLink API</a> over TCP port <code>4560</code> with lockstep synchronization.</p><p>PteroSim runs on <strong>Windows 10/11</strong> and <strong>Ubuntu 22.04+</strong> (64-bit). Install PteroSim from <a href="https://github.com/PteroLabsAI/PteroSim-UAV-Simulator/releases" target="_blank" rel="noreferrer">GitHub Releases</a> and set up PX4 SITL using the <a href="./../dev_setup/dev_env">PX4 development environment</a>. For full installation, UI walkthrough, and QGroundControl setup, see the <a href="https://pterosimdocs.readthedocs.io/en/latest/sitl_simulation_px4.html" target="_blank" rel="noreferrer">PteroSim PX4 SITL guide</a>.</p><h2 id="відео" tabindex="-1">Відео <a class="header-anchor" href="#відео" aria-label="Permalink to &quot;Відео&quot;">​</a></h2><p>PX4 tutorial:</p>',6),t("lite-youtube",{videoid:"gUSc84v3f44",title:"PteroSim PX4 tutorial"},null,-1),t("p",null,"PteroSim demo:",-1),t("lite-youtube",{videoid:"4QMwmZL_3O4",title:"PteroSim PX4 demo"},null,-1),i(`<h2 id="підтримувані-транспортні-засоби" tabindex="-1">Підтримувані транспортні засоби <a class="header-anchor" href="#підтримувані-транспортні-засоби" aria-label="Permalink to &quot;Підтримувані транспортні засоби&quot;">​</a></h2><p>The free tier includes the <strong>F450</strong> multicopter, which is covered by the setup steps on this page:</p><table tabindex="0"><thead><tr><th>Транспортний засіб</th><th>Тип</th><th>PX4 target</th></tr></thead><tbody><tr><td>F450</td><td>Мультикоптер</td><td><code>make px4_sitl_default none_iris</code></td></tr></tbody></table><p>Paid licenses also include fixed-wing, VTOL, and helicopter templates with PX4 SITL support. See <a href="https://pterolabs.ai/#pricing" target="_blank" rel="noreferrer">pterolabs.ai</a> for licensing details.</p><h2 id="network-setup" tabindex="-1">Network Setup <a class="header-anchor" href="#network-setup" aria-label="Permalink to &quot;Network Setup&quot;">​</a></h2><p>PX4 connects to PteroSim on TCP port <code>4560</code>.</p><p>When PteroSim and PX4 SITL run on the same Ubuntu machine, the default host <code>localhost</code> is sufficient.</p><p>When PteroSim runs on Windows and PX4 runs in WSL2, set <code>PX4_SIM_HOSTNAME</code> in the WSL2 shell to the Windows host IP before starting PX4:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> PX4_SIM_HOSTNAME</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> route</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> awk</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;/default/ {print $3; exit}&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><p>Make sure inbound TCP port <code>4560</code> is allowed by the firewall on the PteroSim host.</p><h2 id="запуск-sitl" tabindex="-1">Запуск SITL <a class="header-anchor" href="#запуск-sitl" aria-label="Permalink to &quot;Запуск SITL&quot;">​</a></h2><ol><li><p>Start PteroSim, spawn the F450, select <strong>PX4</strong> as the control source, and press <strong>Start</strong>.</p></li><li><p>Start PX4 SITL with lockstep enabled. Наприклад:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> PX4-Autopilot</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">PX4_LOCKSTEP</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> PX4_SIM_SPEED_FACTOR</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">1</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> px4_sitl_default</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> none_iris</span></span></code></pre></div><p>On Windows with PX4 in WSL2, include <code>PX4_SIM_HOSTNAME</code> as shown in <a href="#network-setup">Network Setup</a>.</p></li><li><p>Connect <a href="https://qgroundcontrol.com" target="_blank" rel="noreferrer">QGroundControl</a> to PX4 as usual.</p></li></ol><p>PX4 prints <code>Simulator connected on TCP port 4560</code> when the bridge is connected.</p><h2 id="усунення-проблем" tabindex="-1">Усунення проблем <a class="header-anchor" href="#усунення-проблем" aria-label="Permalink to &quot;Усунення проблем&quot;">​</a></h2><p>If PX4 waits for the simulator, verify that PteroSim is running, the simulation has been started, the control source is set to <strong>PX4</strong>, <code>PX4_SIM_HOSTNAME</code> points to the PteroSim host when using WSL2, and TCP port <code>4560</code> is not blocked.</p><p>If PX4 connects but the aircraft does not respond to commands, verify that the control source is set to <strong>PX4</strong> in PteroSim.</p>`,16)])])}const m=s(n,[["render",r]]);export{k as __pageData,m as default};
